def balanceado(s: str) -> bool:
    """
    Verifica si los parentesis, corchetes y llaves del string están bien
    balanceados y anidados. Los demás caracteres se ignoran.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados,
        False en caso contrario.
    """
    open_parens = []
    open_brackets = []
    open_braces = []

    for char in s:
        if char == '(':
            open_parens.append(char)
        elif char == '[':
            open_brackets.append(char)
        elif char == '{':
            open_braces.append(char)
        elif char == ')':
            if not open_parens or open_parens.pop() != '(':
                return False
        elif char == ']':
            if not open_brackets or open_brackets.pop() != '[':
                return False
        elif char == '}':
            if not open_braces or open_braces.pop() != '{':
                return False

    return len(open_parens) == 0 and len(open_brackets) == 0 and len(open_braces) == 0

def anidar(plano: dict) -> dict:
    """
    Convierte un diccionario de claves con puntos en un diccionario anidado.

    Ejemplo: {'a.b': 1} -> {'a': {'b': 1}}

    Args:
        plano: Un diccionario donde las claves pueden contener puntos '.'

    Returns:
        Un diccionario anidado con las claves separadas por puntos.
    """
    result = {}
    for key, value in plano.items():
        if '.' in key:
            parts = key.split('.')
            result = {parts[0]: result}
            result[parts[1]] = value
        else:
            result[key] = value
    return result


